//! 📑️ Genuine TSV receiving frames preserve raw row extents and independent newline metadata.
use super::{TsvSnapshot,LineEnding};
use semio_framework_os_kernel::sqlite_snapshot::{SqliteDatabase,SqliteTable,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase};
use semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::{Direction,Projection,Scalar,AuthoredTable,cell,text_cell,row,push_row,sort,identity_position,parent_range,ordinal,integer,validate_schema,settle};
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::NativeSnapshotBodyWallet;
use std::mem::size_of;
type Result<T>=std::result::Result<T,ValueError>;
pub(super) fn validate_subset(dialect:&semio_framework_artifact_reference::ArtifactDialect,control:&mut SqliteSnapshotControl<'_>,checkpoint:impl FnOnce()->Result<()>)->store::io_schema::IoResult<()>{
 checkpoint().map_err(store::io_schema::IoError::from_value_error)?;
 control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).map_err(store::io_schema::IoError::from_value_error)?;
 if dialect.subset=="*"{return Ok(store::io_schema::IoOutcome::clean(()))}
 Err(store::io_schema::IoError::from_value_error(error(ValueRefusalKind::UnsupportedOwner,"TSV subset has no authored semantic validator")))
}
type Port<'a,'b,'c>=semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::Port<'a,'b,'c,NativeSnapshotBodyWallet>;
const SQL:&str=include_str!("../🗄️.sql");
const NAMES:[&str;3]=["tsv_document","tsv_record","tsv_field"];
fn error(kind:ValueRefusalKind,message:&'static str)->ValueError{ValueError::literal(kind,message)}
fn invalid(message:&'static str)->ValueError{error(ValueRefusalKind::InvalidValue,message)}
fn definition(index:usize)->&'static str{SQL.split(';').filter(|word|!word.trim().is_empty()).nth(index).unwrap().trim()}
fn empty_snapshot()->TsvSnapshot{TsvSnapshot{schema:String::new(),records:Vec::new(),trailing_newline:false,line_ending:LineEnding::Lf}}
fn ending(value:LineEnding)->&'static str{match value{LineEnding::Lf=>"lf",LineEnding::Crlf=>"crlf"}}
fn project(source:&TsvSnapshot,frame:&mut Projection,port:&mut Port<'_,'_,'_>)->Result<()>{
 let limits=port.control.limits();let schema_bytes=(0..3).map(|index|NAMES[index].len()+definition(index).len()).sum::<usize>();if schema_bytes>limits.max_schema_bytes||limits.max_tables<3||limits.max_columns<4{return Err(error(ValueRefusalKind::OwnershipLimit,"TSV authored schema exceeds original ceiling"))}
 let mut fields=0usize;for record in &source.records{port.work(2,0)?;fields=fields.checked_add(record.len()).ok_or_else(||error(ValueRefusalKind::WorkLimit,"TSV field count overflow"))?;port.control.check_rows(1usize.checked_add(source.records.len()).and_then(|count|count.checked_add(fields)).ok_or_else(||error(ValueRefusalKind::WorkLimit,"TSV row count overflow"))?)?;}let total=1+source.records.len()+fields;port.control.check_rows(total)?;
 port.vector(3,&mut frame.database.tables,1)?;for(index,count)in[1,source.records.len(),fields].into_iter().enumerate(){port.work(2,size_of::<SqliteTable>())?;frame.database.tables.push(SqliteTable{name:String::new(),sql:String::new(),rows:Vec::new()});let table=&mut frame.database.tables[index];port.text(NAMES[index],&mut table.name,2)?;port.text(definition(index),&mut table.sql,2)?;port.vector(count,&mut table.rows,2)?;}
 row(frame,1,4,port)?;text_cell(frame,&source.schema,port)?;cell(frame,Scalar::Integer(i64::from(source.trailing_newline)),port)?;text_cell(frame,ending(source.line_ending),port)?;push_row(frame,0,port)?;
 let mut field_id=0usize;for(index,record)in source.records.iter().enumerate(){let record_id=ordinal(index+1)?;row(frame,record_id,3,port)?;cell(frame,Scalar::Integer(1),port)?;cell(frame,Scalar::Integer(ordinal(index)?),port)?;push_row(frame,1,port)?;for(index,value)in record.iter().enumerate(){field_id=field_id.checked_add(1).ok_or_else(||error(ValueRefusalKind::WorkLimit,"TSV field identity overflow"))?;row(frame,ordinal(field_id)?,4,port)?;cell(frame,Scalar::Integer(record_id),port)?;cell(frame,Scalar::Integer(ordinal(index)?),port)?;text_cell(frame,value,port)?;push_row(frame,2,port)?;}}
 port.control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,total,total)
}
#[derive(semio_framework_value::RetireOwned)]
struct Reconstruction{snapshot:TsvSnapshot,records:Vec<usize>,record_ids:Vec<usize>,fields:Vec<usize>,field_ids:Vec<usize>,used_fields:usize}
impl Reconstruction{fn new()->Self{Self{snapshot:empty_snapshot(),records:Vec::new(),record_ids:Vec::new(),fields:Vec::new(),field_ids:Vec::new(),used_fields:0}}}
fn table<'a>(database:&'a SqliteDatabase,name:&str)->Result<&'a SqliteTable>{database.tables.iter().find(|table|table.name.eq_ignore_ascii_case(name)).ok_or_else(||invalid("TSV authored table is missing"))}
fn text(row:&SqliteRow,column:usize)->Result<&str>{match row.values.get(column){Some(SqliteValue::Text(value))=>Ok(value),_=>Err(invalid("TSV text cell is invalid"))}}
fn reconstruct(database:&SqliteDatabase,frame:&mut Reconstruction,port:&mut Port<'_,'_,'_>)->Result<()>{
 let authored=[0,1,2].map(|index|AuthoredTable{name:NAMES[index],declaration:definition(index),columns:[4,3,4][index]});validate_schema(database,&authored,port)?;port.control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;
 let documents=&table(database,NAMES[0])?.rows;if documents.len()!=1||documents[0].rowid!=1||documents[0].values.len()!=4||integer(&documents[0],0)?!=1{return Err(invalid("TSV requires one authored document identity"))}let document=&documents[0];port.control.admit_reconstruction_bytes(8)?;port.work(1,size_of::<bool>())?;frame.snapshot.trailing_newline=match integer(document,2)?{0=>false,1=>true,_=>return Err(invalid("TSV trailing newline requires zero or one"))};let line=text(document,3)?;port.control.admit_reconstruction_bytes(line.len())?;port.work(1,size_of::<LineEnding>())?;frame.snapshot.line_ending=match line{"lf"=>LineEnding::Lf,"crlf"=>LineEnding::Crlf,_=>return Err(invalid("TSV line ending requires exact lf or crlf"))};
 let records=&table(database,NAMES[1])?.rows;let children=&table(database,NAMES[2])?.rows;port.vector(records.len(),&mut frame.records,1)?;port.vector(records.len(),&mut frame.record_ids,1)?;port.vector(children.len(),&mut frame.fields,1)?;port.vector(children.len(),&mut frame.field_ids,1)?;
 for(index,row)in records.iter().enumerate(){port.work(1,0)?;if row.values.len()!=3||row.rowid<=0||integer(row,0)?!=row.rowid||integer(row,1)?!=1{return Err(invalid("TSV record identity or document ownership is invalid"))}port.work(1,2*size_of::<usize>())?;frame.records.push(index);frame.record_ids.push(index);}
 sort(&mut frame.records,port,|a,b|Ok(integer(&records[a],2)?.cmp(&integer(&records[b],2)?)))?;sort(&mut frame.record_ids,port,|a,b|Ok(records[a].rowid.cmp(&records[b].rowid)))?;for pair in frame.record_ids.windows(2){port.work(1,0)?;if records[pair[0]].rowid==records[pair[1]].rowid{return Err(invalid("TSV record identity is duplicated"))}}
 for(index,row)in children.iter().enumerate(){port.work(1,0)?;if row.values.len()!=4||row.rowid<=0||integer(row,0)?!=row.rowid{return Err(invalid("TSV field identity or width is invalid"))}if identity_position(records,&frame.record_ids,integer(row,1)?,port)?.is_none(){return Err(invalid("TSV field has an unknown record"))}port.work(1,2*size_of::<usize>())?;frame.fields.push(index);frame.field_ids.push(index);}
 sort(&mut frame.fields,port,|a,b|Ok(integer(&children[a],1)?.cmp(&integer(&children[b],1)?).then(integer(&children[a],2)?.cmp(&integer(&children[b],2)?))))?;sort(&mut frame.field_ids,port,|a,b|Ok(children[a].rowid.cmp(&children[b].rowid)))?;for pair in frame.field_ids.windows(2){port.work(1,0)?;if children[pair[0]].rowid==children[pair[1]].rowid{return Err(invalid("TSV field identity is duplicated"))}}
 let schema=text(document,1)?;port.control.admit_reconstruction_bytes(schema.len())?;port.text(schema,&mut frame.snapshot.schema,1)?;port.vector(records.len(),&mut frame.snapshot.records,2)?;
 for(position,index)in frame.records.iter().copied().enumerate(){let record=&records[index];if integer(record,2)?!=ordinal(position)?{return Err(invalid("TSV record ordinals must be contiguous and unique"))}let members=parent_range(children,&frame.fields,record.rowid,1,port)?;port.work(2,size_of::<Vec<String>>())?;frame.snapshot.records.push(Vec::new());let output=frame.snapshot.records.last_mut().unwrap();port.vector(members.len(),output,3)?;for(position,index)in members.enumerate(){let row=&children[frame.fields[index]];port.work(3,0)?;if integer(row,2)?!=ordinal(position)?{return Err(invalid("TSV field ordinals must be contiguous and unique"))}port.work(3,size_of::<String>())?;output.push(String::new());let value=text(row,3)?;port.control.admit_reconstruction_bytes(value.len())?;port.text(value,output.last_mut().unwrap(),4)?;port.work(3,size_of::<usize>())?;frame.used_fields+=1;}}
 if frame.used_fields!=children.len(){return Err(invalid("TSV field consumption is incomplete"))}let total=1+records.len()+children.len();port.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,total,total)
}
pub(super)fn project_receiving(source:&TsvSnapshot,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>)->Result<SqliteDatabase>{let result=(||{let remaining=control.allocation_remaining_bytes();if remaining==0{return Err(error(ValueRefusalKind::OwnershipLimit,"TSV projection has no original backing allowance"))}let before=owner.native().owned_bytes();let maximum=before.checked_add(remaining).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"TSV original allocation ceiling overflow"))?;let result=owner.scoped_native(maximum,&mut |_|true,|owner|owner.receive::<Projection,SqliteDatabase>(|slot,native,body|{let mut port=Port{control,native:Direction::Decode(native),body};port.work(1,size_of::<Projection>())?;*slot=Some(Projection::new());let frame=slot.as_mut().unwrap();project(source,frame,&mut port)?;port.work(1,size_of::<SqliteDatabase>())?;Ok(std::mem::replace(&mut frame.database,SqliteDatabase{tables:Vec::new()}))}));settle(control,remaining,before,owner.native().owned_bytes())?;result})();result.map_err(|error|error.with_retained_progress(owner.progress()))}
pub(super)fn reconstruct_receiving(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotEncodeOwner<'_,'_>)->Result<TsvSnapshot>{let result=(||{let remaining=control.allocation_remaining_bytes();if remaining==0{return Err(error(ValueRefusalKind::OwnershipLimit,"TSV reconstruction has no original backing allowance"))}let before=owner.native().owned_bytes();let maximum=before.checked_add(remaining).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"TSV original allocation ceiling overflow"))?;let result=owner.scoped_native(maximum,&mut |_|true,|owner|owner.receive::<Reconstruction,TsvSnapshot>(|slot,native,body|{let mut port=Port{control,native:Direction::Encode(native),body};port.work(1,size_of::<Reconstruction>())?;*slot=Some(Reconstruction::new());let frame=slot.as_mut().unwrap();reconstruct(database,frame,&mut port)?;port.work(1,size_of::<TsvSnapshot>())?;Ok(std::mem::replace(&mut frame.snapshot,empty_snapshot()))}));settle(control,remaining,before,owner.native().owned_bytes())?;result})();result.map_err(|error|error.with_retained_progress(owner.progress()))}
